def compute(vars):
    total = vars["v1"] + vars["v2"]
    return {
        "value": total,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "total_after_tax_gains": total,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
